#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
if [ "$ready" != 1 ]; then
  echo "bin/e2e: the app did not become healthy on port ${PORT} within 300s; see .run/app.log" >&2
  exit 2
fi

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
  /** The person's cuts across every pool they are a member of, added up; a pool that shows no cuts adds nothing. */
  protected cutTotalOf(person: Person): string {
    return this.pools()?.cutTotals().get(person.id) ?? '0.00';
  }

  /** How far the sum of the person's dues plus their cut total is above the sheet's cap; 0.00 when it is not. */
  protected excessOf(person: Person): string {
    return excessOver(this.uncappedDueTotalOf(person), this.session.cap(), this.cutTotalOf(person));
  }

  /**
   * The sum of the person's dues as {@link dueTotalOf} has it, before the cap: each of their claims' less the parts
   * its holders have, and the parts they hold of the claims shared with them (which make it a figure, not n/a).
   */
  private uncappedDueTotalOf(person: Person): string {
    const counted = this.claimsOf(person.id).filter((c) => live(c, person, this.session.today()));
    const dues = counted.map((c) => claimDue(c, this.rates(), person.grades, this.session));
    const held = this.heldParts().get(person.id) ?? [];
    const today = this.session.today();
    // A due under a grade the person had on an earlier date counts too.
    const anyDated = today !== null && counted.some((c, i) => dues[i] !== 'n/a' && c.date <= today);
    if (this.rateOf(this.gradeOf(person)) === undefined && !counted.some(dueFixed) && !anyDated && held.length === 0) {
      return 'n/a';
    }
    return sumDues([...counted.map((c, i) => this.ownPartOf(c, dues[i])), ...held.map((h) => h.part)]);
  }

  /**
   * The parts of the shared claims each person holds, by holder id: for each claim that counts in its own person's live
   * totals and has a due, the due times the holder's share divided by 100, rounded half to even.
   */

